# /etc/nginx/nginx.conf — blok http
http {
    thread_pool download_pool threads=16 max_queue=65536;

    server {
        listen 443 ssl;
        server_name files.contoh.id;

        location /besar/ {
            alias /var/www/files/;
            aio threads=download_pool;  # baca disk async, worker tidak blokir
            directio 4m;
            output_buffers 1 512k;
        }
    }
}

# 1. Aplikasi (Node.js/Express) — hanya cek izin, lalu lempar ke NGINX
app.get('/download/:id', async (req, res) => {
  const file = await db.files.findById(req.params.id);
  if (!file || file.ownerId !== req.user.id) {
    return res.status(403).send('Tidak ada akses');
  }
  // Jangan kirim file di sini — beri tahu NGINX saja:
  res.set('Content-Type', file.mimeType);
  res.set('Content-Disposition', `attachment; filename="${file.name}"`);
  res.set('X-Accel-Redirect', `/protected/${file.storedName}`);
  res.status(200).end();
});

# 2. NGINX — location internal yang hanya bisa diakses via X-Accel-Redirect
server {
    listen 443 ssl;
    server_name files.contoh.id;

    location /protected/ {
        internal;  # TIDAK bisa diakses langsung dari browser!
        alias /var/www/private-files/;
        sendfile on;
        tcp_nopush on;
    }
}

# Uji: akses langsung harus 404
# curl -I https://files.contoh.id/protected/rahasia.pdf  -> 404 Not Found
# curl -I https://files.contoh.id/download/123 (dengan login) -> 200 + file

# /etc/nginx/conf.d/files.conf
location /download/ {
    alias /var/www/files/;
    sendfile on;

    # Range request AKTIF secara default — jangan dimatikan:
    max_ranges 0;  # 0 = tanpa batas jumlah range per request (default)

    # Paksa browser mengunduh, bukan menampilkan di tab
    add_header Content-Disposition 'attachment';

    # Cache header: file statis boleh di-cache browser 7 hari
    expires 7d;
    add_header Cache-Control "public, immutable";
}

